get items() {
  return [...this._items.values()].map(({product, qty}) => ({
    product,
    qty,
    lineTotalCents: product.priceCents * qty,
  }));
}

get count() {
  let total = 0;
  for (const { qty } of this._items.values()) total += qty;
  return total;
}

get isEmpty() { return this._items.size === 0; }
