PricingEngine:

```js
export class PricingEngine {
  constructor({ rules = [] } = {}) {
    this.rules = [...rules].sort((a,b) => (a.priority ?? 100) - (b.priority ?? 100));
  }

  register(rule) {
    this.rules.push(rule);
    this.rules.sort(...);
    return this;
  }

  calculate(state) {
    const items = state.items ?? [];
    const subtotalCents = items.reduce((sum, item) => sum + item.priceCents * item.qty, 0);
    const context = {
      items,
      coupon: state.coupon ?? null,
      currency: state.currency ?? 'EUR',
      subtotalCents,
      discountedSubtotalCents: subtotalCents,
      discountCents: 0,
      discounts: [],
      shippingCents: 0,
      taxCents: 0,
      totalCents: subtotalCents,
      metadata: {},
      addDiscount({ label, amountCents, code = null }) { ... }
    };
    for (const rule of this.rules) {
      const result = rule.apply(context);
      if (result && typeof result === 'object') Object.assign(context, ...?) 
    }
    context.totalCents = Math.max(0, context.discountedSubtotalCents + context.shippingCents + context.taxCents);
    return {
      itemCount: ...,
      subtotalCents,
      discountCents,
      discounts,
      shippingCents,
      taxCents,
      totalCents,
      currency,
      ...metadata
    };
  }
}
```

Rules mutate context. Let's define addDiscount on context:

```js
addDiscount({ label, amountCents, code = null }) {
  const amount = Math.max(0, Math.round(amountCents));
  if (amount === 0) return;
  context.discounts.push({ label, amountCents: amount, code });
  context.discountCents += amount;
  context.discountedSubtotalCents = Math.max(0, context.discountedSubtotalCents - amount);
}
```

