Rules in rules.js:

```js
export const VolumeDiscountRule = ({ minQty = 3, rate = 0.1, label = 'Descuento por volumen' } = {}) => ({
  name: 'volume-discount',
  priority: 10,
  apply(context) {
    for (const item of context.items) {
      if (item.qty < minQty) continue;
      const amount = Math.round(item.priceCents * item.qty * rate);
      context.addDiscount({ label: `${label} (${item.name})`, amountCents: amount });
    }
  },
});
```

But careful: sequential discounts subtract from discounted subtotal; volume per line computed on gross line amount, that's fine.

CouponRule:

```js
export const CouponRule = ({ coupons = [] } = {}) => ({
  name: 'coupon',
  priority: 20,
  apply(context) {
    const coupon = context.coupon;
    if (!coupon) return;
    const definition = coupons.find((c) => c.code === coupon.code) ?? coupon;
    if (!definition) return;
    const min = definition.minSubtotalCents ?? 0;
    if (context.subtotalCents < min) {
      context.metadata.couponError = `El cupón requiere un mínimo de ...`;
      context.metadata.couponApplied = false;
      return;
    }
    let amount = 0;
    if (definition.type === 'percent') {
      amount = Math.round(context.discountedSubtotalCents * (definition.value / 100));
    } else {
      amount = Math.round(definition.value); // value in cents for fixed
    }
    amount = Math.min(amount, context.discountedSubtotalCents);
    context.addDiscount({ label: `Cupón ${definition.code}`, amountCents: amount, code: definition.code });
    context.metadata.couponApplied = true;
    context.metadata.couponLabel = definition.description ?? ...
  }
});
```

For fixed coupons, define valueCents. Let's make coupon catalog shape: {code, type:'percent'|'fixed', value, minSubtotalCents, description}. For percent value=10 means 10%; for fixed value=500 means 5.00€ (cents). Document.

ShippingRule:

```js
export const ShippingRule = ({ freeThresholdCents = 5000, baseCents = 499 } = {}) => ({
  name: 'shipping',
  priority: 30,
  apply(context) {
    if (context.items.length === 0) { context.shippingCents = 0; return; }
    const remaining = Math.max(0, freeThresholdCents - context.discountedSubtotalCents);
    context.shippingCents = remaining === 0 ? 0 : baseCents;
    context.metadata.freeShippingThresholdCents = freeThresholdCents;
    context.metadata.freeShippingRemainingCents = remaining;
    context.metadata.freeShippingReached = remaining === 0;
  }
});
```

TaxRule:

```js
export const TaxRule = ({ rate = 0.21, label = 'IVA (21%)' } = {}) => ({
  name: 'tax',
  priority: 40,
  apply(context) {
    const taxable = context.discountedSubtotalCents + context.shippingCents;
    context.taxCents = Math.round(taxable * rate);
    context.metadata.taxRate = rate;
    context.metadata.taxLabel = label;
  }
});
```

