export class CheckoutService {
  constructor({ clock = () => new Date(), idGenerator = defaultId } = {}) {}
  process(cart, { customer = {} } = {}) {
    if (!cart || cart.isEmpty) throw new Error('El carrito está vacío');
    const totals = cart.totals();
    if (!totals || totals.totalCents < 0) throw ...
    const order = {
      id: this.idGenerator(),
      createdAt: this.clock().toISOString(),
      items: cart.items.map(...),
      totals,
      customer: {...},
      status: 'confirmed',
    };
    cart.clear();
    return order;
  }
}
```

