storage adapters:

```js
export class LocalStorageAdapter {
  constructor({ key = 'cca:cart', storage = globalThis.localStorage } = {}) {
    this.key = key;
    this.storage = storage;
  }
  load() {
    try {
      const raw = this.storage?.getItem(this.key);
      return raw ? JSON.parse(raw) : null;
    } catch { return null; }
  }
  save(state) {
    try { this.storage?.setItem(this.key, JSON.stringify(state)); } catch {}
  }
  clear() { try { this.storage?.removeItem(this.key); } catch {} }
}
```

Memory:

```js
export class MemoryStorageAdapter {
  constructor(initial = null) { this.state = initial; }
  load() { return this.state ? JSON.parse(JSON.stringify(this.state)) : null; }
  save(state) { this.state = JSON.parse(JSON.stringify(state)); }
  clear() { this.state = null; }
}
