import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { extname, join, normalize, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('.', import.meta.url));
const port = Number(process.env.PORT) || 4173;

const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
};

const server = createServer(async (request, response) => {
  try {
    const url = new URL(request.url ?? '/', `http://${request.headers.host}`);
    const pathname = decodeURIComponent(url.pathname);
    let filePath = resolve(root, `.${normalize(pathname)}`);

    if (!filePath.startsWith(root)) {
      response.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
      response.end('Acceso denegado');
      return;
    }

    let info = await stat(filePath).catch(() => null);

    if (info?.isDirectory()) {
      filePath = join(filePath, 'index.html');
      info = await stat(filePath).catch(() => null);
    }

    if (!info?.isFile()) {
      response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      response.end('Recurso no encontrado');
      return;
    }

    const body = await readFile(filePath);
    response.writeHead(200, {
      'Content-Type': MIME_TYPES[extname(filePath)] ?? 'application/octet-stream',
      'Cache-Control': 'no-cache',
    });
    response.end(body);
  } catch {
    response.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
    response.end('Error interno');
  }
});

server.listen(port, () => {
  console.log(`Nébula Store disponible en http://localhost:${port}`);
});

export class EventEmitter {
  constructor() {
    this._listeners = new Map();
  }

  on(event, listener) {
    if (typeof listener !== 'function') {
      throw new TypeError('El listener debe ser una función');
    }
    if (!this._listeners.has(event)) {
      this._listeners.set(event, new Set());
    }
    this._listeners.get(event).add(listener);
    return () => this.off(event, listener);
  }

  once(event, listener) {
    const unsubscribe = this.on(event, (payload) => {
      unsubscribe();
      listener(payload);
    });
    return unsubscribe;
  }

  off(event, listener) {
    this._listeners.get(event)?.delete(listener);
  }

  emit(event, payload) {
    this._listeners.get(event)?.forEach((listener) => {
      try {
        listener(payload);
      } catch (error) {
        console.error(`Error en listener de "${event}"`, error);
      }
    });
  }
}

export function toCents(value) {
  return Math.round(Number(value) * 100);
}

export function fromCents(cents) {
  return Number(cents) / 100;
}

export function formatMoney(cents, { currency = 'EUR', locale = 'es-ES' } = {}) {
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
  }).format((Number(cents) || 0) / 100);
}

import { EventEmitter } from './EventEmitter.js';
import { toCents } from './money.js';

const DEFAULT_QTY = 1;
const MAX_QTY = 99;

export class Cart extends EventEmitter {
  constructor({ storage = null, pricing = null, currency = 'EUR', autoPersist = true } = {}) {
    super();
    this.storage = storage;
    this.pricing = pricing;
    this.currency = currency;
    this.autoPersist = autoPersist;
    this._items = new Map();
    this.coupon = null;
    this._load();
  }

  get items() {
    return [...this._items.values()].map(({ product, qty }) => ({
      product,
      qty,
      lineTotalCents: this._priceOf(product) * qty,
    }));
  }

  get count() {
    let total = 0;
    for (const { qty } of this._items.values()) {
      total += qty;
    }
    return total;
  }

  get isEmpty() {
    return this._items.size === 0;
  }

  get state() {
    return {
      items: this.items.map(({ product, qty }) => ({
        productId: product.id,
        name: product.name,
        category: product.category,
        priceCents: this._priceOf(product),
        qty,
      })),
      coupon: this.coupon,
      currency: this.currency,
    };
  }

  add(product, qty = DEFAULT_QTY) {
    if (!product?.id) {
      throw new TypeError('El producto debe tener un id');
    }

    const quantity = this._normalizeQty(qty);
    const priceCents = product.priceCents ?? toCents(product.price);
    const existing = this._items.get(product.id);

    if (existing) {
      existing.qty = Math.min(MAX_QTY, existing.qty + quantity);
    } else {
      this._items.set(product.id, {
        product: { ...product, priceCents },
        qty: quantity,
      });
    }

    this._commit('cart:item-added', { productId: product.id, qty: quantity });
    return this;
  }

  setQty(productId, qty) {
    const item = this._items.get(productId);
    if (!item) {
      return this;
    }

    const quantity = Number(qty);
    if (!Number.isFinite(quantity) || quantity <= 0) {
      return this.remove(productId);
    }

    item.qty = Math.min(MAX_QTY, Math.floor(quantity));
    this._commit('cart:item-updated', { productId, qty: item.qty });
    return this;
  }

  increment(productId, delta = 1) {
    const item = this._items.get(productId);
    if (!item) {
      return this;
    }
    return this.setQty(productId, item.qty + Number(delta));
  }

  remove(productId) {
    if (!this._items.delete(productId)) {
      return this;
    }
    if (this._items.size === 0) {
      this.coupon = null;
    }
    this._commit('cart:item-removed', { productId });
    return this;
  }

  clear() {
    if (this._items.size === 0 && !this.coupon) {
      return this;
    }
    this._items.clear();
    this.coupon = null;
    this._commit('cart:cleared');
    return this;
  }

  applyCoupon(coupon) {
    if (!coupon || typeof coupon !== 'object' || !coupon.code) {
      throw new TypeError('Cupón inválido');
    }
    this.coupon = { ...coupon };
    this._commit('cart:coupon-applied', { code: coupon.code });
    return this;
  }

  removeCoupon() {
    if (!this.coupon) {
      return this;
    }
    this.coupon = null;
    this._commit('cart:coupon-removed');
    return this;
  }

  totals() {
    return this.pricing ? this.pricing.calculate(this.state) : null;
  }

  serialize() {
    return {
      items: this.items.map(({ product, qty }) => ({
        product: {
          id: product.id,
          name: product.name,
          category: product.category,
          image: product.image,
          color: product.color,
          priceCents: this._priceOf(product),
        },
        qty,
      })),
      coupon: this.coupon,
    };
  }

  hydrate(state, { silent = false } = {}) {
    if (!state || typeof state !== 'object') {
      return this;
    }

    this._items.clear();
    for (const entry of state.items ?? []) {
      const product = entry.product ?? entry;
      if (!product?.id) {
        continue;
      }
      const priceCents = product.priceCents ?? toCents(product.price);
      const qty = Math.max(1, Math.min(MAX_QTY, Math.floor(Number(entry.qty) || DEFAULT_QTY)));
      this._items.set(product.id, {
        product: { ...product, priceCents },
        qty,
      });
    }
    this.coupon = state.coupon ?? null;

    if (!silent) {
      this._commit('cart:hydrated');
    }
    return this;
  }

  _load() {
    if (!this.storage) {
      return;
    }
    const state = this.storage.load();
    if (state) {
      this.hydrate(state, { silent: true });
    }
  }

  _priceOf(product) {
    return product.priceCents ?? toCents(product.price);
  }

  _normalizeQty(qty) {
    const quantity = Math.floor(Number(qty));
    if (!Number.isFinite(quantity) || quantity <= 0) {
      return DEFAULT_QTY;
    }
    return Math.min(MAX_QTY, quantity);
  }

  _commit(event, detail = {}) {
    this.emit('change', { event, ...detail, cart: this });
    this.emit(event, detail);
    if (this.autoPersist && this.storage) {
      this.storage.save(this.serialize());
    }
  }
}

export class PricingEngine {
  constructor({ rules = [] } = {}) {
    this.rules = [];
    for (const rule of rules) {
      this.register(rule);
    }
  }

  register(rule) {
    if (!rule || typeof rule.apply !== 'function') {
      throw new TypeError('La regla de precio debe implementar apply(context)');
    }
    this.rules.push(rule);
    this.rules.sort((a, b) => (a.priority ?? 100) - (b.priority ?? 100));
    return this;
  }

  calculate(state = {}) {
    const items = state.items ?? [];
    const currency = state.currency ?? 'EUR';
    const subtotalCents = items.reduce(
      (sum, item) => sum + (Number(item.priceCents) || 0) * (Number(item.qty) || 0),
      0,
    );

    const context = {
      items,
      coupon: state.coupon ?? null,
      currency,
      subtotalCents,
      discountedSubtotalCents: subtotalCents,
      discountCents: 0,
      discounts: [],
      shippingCents: 0,
      taxCents: 0,
      totalCents: subtotalCents,
      metadata: {},
    };

    context.addDiscount = ({ label, amountCents, code = null }) => {
      const amount = Math.max(0, Math.round(Number(amountCents) || 0));
      if (amount === 0) {
        return;
      }
      const capped = Math.min(amount, context.discountedSubtotalCents);
      context.discounts.push({ label, amountCents: capped, code });
      context.discountCents += capped;
      context.discountedSubtotalCents -= capped;
    };

    for (const rule of this.rules) {
      rule.apply(context);
    }

    context.totalCents = Math.max(
      0,
      context.discountedSubtotalCents + context.shippingCents + context.taxCents,
    );

    return {
      itemCount: items.reduce((sum, item) => sum + (Number(item.qty) || 0), 0),
      subtotalCents: context.subtotalCents,
      discountCents: context.discountCents,
      discounts: context.discounts,
      shippingCents: context.shippingCents,
      taxCents: context.taxCents,
      totalCents: context.totalCents,
      currency,
      ...context.metadata,
    };
  }
}

import { formatMoney } from '../money.js';

export function VolumeDiscountRule({ minQty = 3, rate = 0.1, label = 'Descuento por volumen' } = {}) {
  return {
    name: 'volume-discount',
    priority: 10,
    apply(context) {
      for (const item of context.items) {
        if (item.qty < minQty) {
          continue;
        }
        const lineTotal = item.priceCents * item.qty;
        context.addDiscount({
          label: `${label} · ${item.name}`,
          amountCents: Math.round(lineTotal * rate),
        });
      }
    },
  };
}

export function CouponRule({ coupons = [] } = {}) {
  return {
    name: 'coupon',
    priority: 20,
    apply(context) {
      if (!context.coupon) {
        return;
      }

      const coupon = coupons.find((entry) => entry.code === context.coupon.code) ?? context.coupon;
      const minSubtotal = coupon.minSubtotalCents ?? 0;

      if (context.subtotalCents < minSubtotal) {
        context.metadata.couponApplied = false;
        context.metadata.couponError =
          `El cupón ${coupon.code} requiere un mínimo de ${formatMoney(minSubtotal, { currency: context.currency })}.`;
        return;
      }

      const amount =
        coupon.type === 'percent'
          ? Math.round(context.discountedSubtotalCents * (Number(coupon.value) / 100))
          : Number(coupon.value);

      context.addDiscount({
        label: coupon.description ?? `Cupón ${coupon.code}`,
        amountCents: amount,
        code: coupon.code,
      });
      context.metadata.couponApplied = true;
      context.metadata.couponCode = coupon.code;
    },
  };
}

export function ShippingRule({ freeThresholdCents = 5000, baseCents = 499 } = {}) {
  return {
    name: 'shipping',
    priority: 30,
    apply(context) {
      if (context.items.length === 0) {
        context.shippingCents = 0;
        context.metadata.freeShippingReached = false;
        context.metadata.freeShippingRemainingCents = freeThresholdCents;
        context.metadata.freeShippingThresholdCents = freeThresholdCents;
        return;
      }

      const remaining = Math.max(0, freeThresholdCents - context.discountedSubtotalCents);
      context.shippingCents = remaining === 0 ? 0 : baseCents;
      context.metadata.freeShippingThresholdCents = freeThresholdCents;
      context.metadata.freeShippingRemainingCents = remaining;
      context.metadata.freeShippingReached = remaining === 0;
    },
  };
}

export function TaxRule({ rate = 0.21, label = 'IVA (21%)' } = {}) {
  return {
    name: 'tax',
    priority: 40,
    apply(context) {
      const taxable = context.discountedSubtotalCents + context.shippingCents;
      context.taxCents = Math.round(taxable * rate);
      context.metadata.taxRate = rate;
      context.metadata.taxLabel = label;
    },
  };
}

export class LocalStorageAdapter {
  constructor({ key = 'nebula:cart:v1', storage = globalThis.localStorage } = {}) {
    this.key = key;
    this.storage = storage;
  }

  load() {
    try {
      const raw = this.storage?.getItem(this.key);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }

  save(state) {
    try {
      this.storage?.setItem(this.key, JSON.stringify(state));
    } catch {
      return false;
    }
    return true;
  }

  clear() {
    try {
      this.storage?.removeItem(this.key);
    } catch {
      return false;
    }
    return true;
  }
}

export class MemoryStorageAdapter {
  constructor(initialState = null) {
    this.state = initialState ? structuredClone(initialState) : null;
  }

  load() {
    return this.state ? structuredClone(this.state) : null;
  }

  save(state) {
    this.state = structuredClone(state);
    return true;
  }

  clear() {
    this.state = null;
    return true;
  }
}

export const coupons = [
  {
    code: 'BIENVENIDO10',
    type: 'percent',
    value: 10,
    minSubtotalCents: 0,
    description: 'Bienvenida · 10 % de descuento',
  },
  {
    code: 'AHORRA15',
    type: 'percent',
    value: 15,
    minSubtotalCents: 8000,
    description: '15 % en compras desde 80 €',
  },
  {
    code: 'CINCO',
    type: 'fixed',
    value: 500,
    minSubtotalCents: 3000,
    description: '5 € de descuento directo',
  },
];

import { PricingEngine } from '../core/pricing/PricingEngine.js';
import {
  CouponRule,
  ShippingRule,
  TaxRule,
  VolumeDiscountRule,
} from '../core/pricing/rules.js';
import { coupons } from '../data/coupons.js';

export const shippingConfig = {
  freeThresholdCents: 5000,
  baseCents: 499,
};

export const taxConfig = {
  rate: 0.21,
  label: 'IVA (21 %)',
};

export function createDefaultPricing() {
  return new PricingEngine({
    rules: [
      VolumeDiscountRule({ minQty: 3, rate: 0.1 }),
      CouponRule({ coupons }),
      ShippingRule(shippingConfig),
      TaxRule(taxConfig),
    ],
  });
}

function defaultIdGenerator() {
  if (globalThis.crypto?.randomUUID) {
    return `ORD-${globalThis.crypto.randomUUID().slice(0, 8).toUpperCase()}`;
  }
  return `ORD-${Date.now().toString(36).toUpperCase()}`;
}

export class CheckoutService {
  constructor({ clock = () => new Date(), idGenerator = defaultIdGenerator } = {}) {
    this.clock = clock;
    this.idGenerator = idGenerator;
  }

  process(cart, { customer = {} } = {}) {
    if (!cart) {
      throw new Error('No se recibió un carrito');
    }
    if (cart.isEmpty) {
      throw new Error('El carrito está vacío');
    }

    const totals = cart.totals();
    if (!totals || totals.totalCents <= 0) {
      throw new Error('No se pudo calcular el total del pedido');
    }

    const order = {
      id: this.idGenerator(),
      createdAt: this.clock().toISOString(),
      status: 'confirmed',
      customer: { ...customer },
      items: cart.items.map(({ product, qty, lineTotalCents }) => ({
        productId: product.id,
        name: product.name,
        unitPriceCents: product.priceCents,
        qty,
        lineTotalCents,
      })),
      totals,
    };

    cart.clear();
    return order;
  }
}

