Focus trap:

```js
function trapFocus(event) {
  if (event.key !== 'Tab' || els.panel.hidden) return;
  const focusables = els.panel.querySelectorAll('button:not([disabled]), input:not([disabled]), select:not([disabled]), [href], [tabindex]:not([tabindex="-1"])');
  const visible = [...focusables].filter(el => el.offsetParent !== null || el === document.activeElement);
  if (visible.length === 0) return;
  const first = visible[0], last = visible[visible.length - 1];
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
}
```

