import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import { rm } from 'node:fs/promises';

const PORT = 4188;
const DEBUG_PORT = 9333;

await rm('/tmp/cca_chrome_profile', { recursive: true, force: true });

const chrome = spawn(
  'google-chrome',
  [
    '--headless=new',
    '--no-sandbox',
    '--disable-gpu',
    `--remote-debugging-port=${DEBUG_PORT}`,
    '--user-data-dir=/tmp/cca_chrome_profile',
    '--window-size=1440,1100',
    'about:blank',
  ],
  { stdio: 'ignore' },
);

let targets = [];
for (let i = 0; i < 50; i += 1) {
  try {
    const response = await fetch(`http://127.0.0.1:${DEBUG_PORT}/json/list`);
    targets = await response.json();
    if (targets.length > 0) break;
  } catch {}
  await sleep(200);
}

const page = targets.find((target) => target.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.onopen = resolve;
  ws.onerror = reject;
});

let nextId = 0;
const pending = new Map();
ws.onmessage = (event) => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    if (message.error) reject(new Error(JSON.stringify(message.error)));
    else resolve(message.result);
  }
};

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

async function evaluate(expression) {
  const result = await send('Runtime.evaluate', {
    expression,
    awaitPromise: true,
    returnByValue: true,
  });
  if (result.exceptionDetails) {
    throw new Error(result.exceptionDetails.text ?? 'Error de evaluación');
  }
  return result.result.value;
}

await send('Page.enable');
await send('Runtime.enable');
await send('Page.navigate', { url: `http://localhost:${PORT}/` });

for (let i = 0; i < 40; i += 1) {
  const count = await evaluate("document.querySelectorAll('.product-card').length");
  if (count > 0) break;
  await sleep(100);
}

const results = {};
results.productCount = await evaluate("document.querySelectorAll('.product-card').length");
results.badgeInitiallyHidden = await evaluate("document.querySelector('#cart-badge').hidden");

await evaluate("document.querySelector('[data-add=\"aurora-headphones\"]').click()");
await sleep(150);
results.badgeAfterAdd = await evaluate("document.querySelector('#cart-badge').textContent");
results.addButtonLabel = await evaluate(
  "document.querySelector('[data-add=\"aurora-headphones\"]').textContent.trim()",
);

await evaluate("document.querySelector('[data-add=\"aurora-headphones\"]').click()");
await evaluate("document.querySelector('[data-add=\"nomad-bottle\"]').click()");
await sleep(150);
results.badgeAfterMore = await evaluate("document.querySelector('#cart-badge').textContent");
results.cartLines = await evaluate("document.querySelectorAll('.cart-item').length");

await evaluate("document.querySelector('#cart-toggle').click()");
await sleep(100);
results.cartOpen = await evaluate("!document.querySelector('#cart-panel').hidden");
results.footerVisible = await evaluate("!document.querySelector('#cart-footer').hidden");
results.totalBeforeCoupon = await evaluate(
  "document.querySelector('#totals .total-row:last-child')?.textContent",
);
results.shippingMessage = await evaluate(
  "document.querySelector('#shipping-message').textContent.trim()",
);

await evaluate(`
  const input = document.querySelector('#coupon-input');
  input.value = 'BIENVENIDO10';
  document.querySelector('#coupon-form').requestSubmit();
`);
await sleep(150);
results.appliedCoupon = await evaluate(
  "document.querySelector('#applied-coupon')?.textContent.replace(/\\s+/g, ' ').trim()",
);
results.discountRow = await evaluate(
  "document.querySelector('#totals .discount')?.textContent.trim()",
);
results.totalAfterCoupon = await evaluate(
  "document.querySelector('#totals .total-row:last-child')?.textContent",
);

await evaluate("document.querySelector('[data-increment=\"nomad-bottle\"]').click()");
await sleep(120);
results.badgeAfterIncrement = await evaluate("document.querySelector('#cart-badge').textContent");
results.bottleQty = await evaluate(
  "document.querySelector('.cart-item[data-id=\"nomad-bottle\"] .qty span').textContent",
);

await evaluate("document.querySelector('#checkout-button').click()");
await sleep(250);
results.orderDialogOpen = await evaluate("document.querySelector('#order-dialog').open");
results.orderSummary = await evaluate("document.querySelector('#order-summary').textContent");
results.badgeAfterCheckout = await evaluate("document.querySelector('#cart-badge').hidden");

await evaluate("document.querySelector('#order-close').click()");
await sleep(150);
results.reloadPersistence = await evaluate("localStorage.getItem('nebula:cart:v1')");

console.log(JSON.stringify(results, null, 2));

ws.close();
chrome.kill('SIGKILL');
